"""Template-matched real-text slides with large editorial infographic artwork."""
from content import ROOT, Path
from slides import SLIDES, CORE_COUNT
from html import escape as E
BUILD=Path('/tmp/nspa-workshop/build');BUILD.mkdir(parents=True,exist_ok=True)
css='''*{box-sizing:border-box}body{margin:0;color:#2e4f66;font-family:Arial,sans-serif}.slide{width:1536px;height:864px;position:relative;overflow:hidden;background:#fff url("FOOTER") center/100% 100% no-repeat}.heading{position:absolute;left:90px;right:90px;top:52px}h1{font:700 48px/1.1 Arial,sans-serif;color:#ff7233;margin:0 0 13px;letter-spacing:-.8px}.subtitle{font-size:28px;line-height:1.25;margin:0}.content{position:absolute;left:90px;right:90px;top:188px;height:452px;display:flex;align-items:center;gap:50px}.diagram-art,.photo-img{width:780px;height:452px;object-fit:contain;flex-shrink:0}.photo-img{object-fit:cover}.text-stack{flex:1;min-width:0}.text-row{margin:0 0 29px}.text-row:last-child{margin:0}.text-row h2{font-size:31px;line-height:1.16;color:#007681;margin:0 0 10px}.text-row p{font-size:28px;line-height:1.3;margin:0}.action{position:absolute;left:90px;right:90px;top:680px;min-height:44px;border-top:3px solid #ffcd34;padding-top:12px;font-size:26px;line-height:1.25;font-weight:bold}.resource-links{position:absolute;left:90px;top:735px;display:flex;gap:20px;z-index:5}.resource-link{display:flex;align-items:center;justify-content:space-between;width:432px;height:34px;padding:4px 14px;background:#007681;color:white;text-decoration:none;font:bold 20px Arial}.official-logo{position:absolute;left:340px;bottom:10px;width:98px;height:62px;object-fit:contain}.page-number{position:absolute;left:470px;bottom:27px;font-size:20px;color:#007681}.photo-note{position:absolute;right:90px;top:649px;font-size:15px;color:#526674}.content.panorama{display:block;top:188px;height:475px}.panorama .diagram-art{width:100%;height:338px;object-fit:contain;display:block;margin:0 auto 14px}.diagram-labels{display:grid;gap:32px;grid-template-columns:repeat(3,minmax(0,1fr))}.diagram-label h2{font-size:29px;line-height:1.15;color:#007681;margin:0 0 10px}.diagram-label p{font-size:26px;line-height:1.25;margin:0}.slide-3 .diagram-labels{grid-template-columns:repeat(4,minmax(0,1fr));gap:24px}.slide-3 .diagram-label h2{font-size:29px}.slide-13 .diagram-labels{grid-template-columns:repeat(5,minmax(0,1fr));gap:22px}.slide-13 .diagram-label h2{font-size:29px}.slide-13 .diagram-label p{font-size:25px}.slide-12 .content{top:211px;height:451px}.slide-12 .diagram-art{height:302px}.slide-12 .diagram-label p{font-size:25px}.silence .diagram-art{width:840px;object-fit:cover}.silence .text-row h2{font-size:58px;line-height:1.05;color:#007681;margin-bottom:30px}.silence .text-row p{font-size:34px;line-height:1.35}.content.sources{display:block;top:205px;height:440px}.sources .text-row{padding:16px 0;margin:0 0 20px;border-bottom:1px solid #cbdfe2;display:flex;align-items:baseline;gap:60px}.sources h2{width:460px;flex-shrink:0;font-size:34px;margin:0}.sources p{font-size:29px}.cover{background-image:url("COVER")}.cover .cover-text{position:absolute;left:100px;top:95px;width:1100px}.cover h1{font-size:64px;line-height:1.1;max-width:1000px;margin-bottom:26px}.cover h2{font-size:35px;line-height:1.3;max-width:1080px;margin:0;font-weight:400;color:#2e4f66}.cover .presenter{position:absolute;left:100px;top:410px;font-size:29px;line-height:1.65}.cover .presenter strong{font-size:34px}.cover .cover-photo{position:absolute;left:818px;top:345px;width:470px;height:306px;object-fit:cover}.cover .cover-logo{position:absolute;left:100px;top:572px;width:115px;height:73px;object-fit:contain}.cover .photo-note{right:248px;top:657px;font-size:13px}'''.replace('FOOTER',f'file://{ROOT}/assets/conference-footer.png').replace('COVER',f'file://{ROOT}/assets/conference-cover.png')

def render_slide(i,s):
 layout=s['layout']
 photo=f'file://{ROOT}/2026/images/photorealistic/{s["photo"]}.png' if s['photo'] else None
 art=f'file://{ROOT}/2026/images/{s["art"]}.png' if s['art'] else None
 if layout=='cover':
  body=f'<div class="cover-text"><h1>TRUST, TRANSPARENCY,<br>AND AI</h1><h2>{E(s["subtitle"])}</h2></div><div class="presenter"><strong>Miguel Guhlin</strong><br>October 21, 2026<br>3:30–5:00 PM CT</div><img class="cover-logo" src="file://{ROOT}/assets/nspa-logo.png" alt="NSPA"><img class="cover-photo" src="{photo}" alt="AI-generated fictional scholarship reviewers"><div class="photo-note">AI-generated image · fictional people</div>'
 else:
  rows=''.join(f'<div class="text-row"><h2>{E(h)}</h2><p>{E(p)}</p></div>' for h,p in s['blocks'])
  if layout=='panorama':
   panels=f'<img class="diagram-art" src="{art}" alt="AI-generated illustration supporting the labeled stages below"><div class="diagram-labels">'+''.join(f'<div class="diagram-label"><h2>{E(h)}</h2><p>{E(p)}</p></div>' for h,p in s['blocks'])+'</div>'
  elif layout=='sources':panels=rows
  else:
   visual=f'<img class="{"photo-img" if photo else "diagram-art"}" src="{photo or art}" alt="{"AI-generated scene of fictional people" if photo else "AI-generated teaching illustration"}">'
   panels=visual+f'<div class="text-stack">{rows}</div>'
  body=f'<header class="heading"><h1>{E(s["title"])}</h1><p class="subtitle">{E(s["subtitle"])}</p></header><div class="content {layout}">{panels}</div><div class="action">{E(s["action"])}</div><img class="official-logo" src="file://{ROOT}/assets/nspa-logo.png" alt="NSPA"><span class="page-number">{i:02}{" · Reference" if i>CORE_COUNT else ""}</span>'
  if photo:body+='<div class="photo-note">AI-generated image · fictional people</div>'
 if s.get('links'):body+='<nav class="resource-links">'+''.join(f'<a class="resource-link" href="{E(link["url"])}"><span>{E(link["label"])}</span><span>↗</span></a>' for link in s['links'])+'</nav>'
 return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><style>{css}</style></head><body><div class="slide {layout} slide-{i}">{body}</div></body></html>'

for i,s in enumerate(SLIDES,1):(BUILD/f'{i:02}.html').write_text(render_slide(i,s))
print('Prepared',len(SLIDES),'slides:',CORE_COUNT,'core + optional appendix')
